for (var i = 0; i < AuditJournal.Capacity + 4; i++) journal.Record(AuditEvent.Started, now.AddSeconds(i));
Check(journal.Read().Count == AuditJournal.Capacity && journal.Read()[0].At == now.AddSeconds(4), "Audit retention is capped at 256 records");
Check(new FileInfo(journal.FilePath).Length < 128 * 1024, "Audit file remains within its small size bound");
Reject(() => new AuditJournal(Path.GetDirectoryName(journal.FilePath)!, otherDevice).Read(), "Protected audit history cannot be read with a foreign device protector");
