Check(!Encoding.UTF8.GetString(protectedHistory).Contains(now.AddSeconds(4).ToString("yyyy-MM-dd")), "Audit timestamps are encrypted at rest");
Reject(() => journal.Record((AuditEvent)999), "Audit accepts only fixed event codes");
