EntryMetadata.MarkSaved(tracked, null, now); var later = Codec.Clone(tracked); EntryMetadata.MarkSaved(later, tracked, now.AddMinutes(1));
Check(later.CreatedAt == now && later.UpdatedAt == now.AddMinutes(1), "Metadata preserves creation time across edits");
